package com.example.web;

import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.server.ResponseStatusException;

@Controller
public class PageController {
    private final PostRepository posts; // your data access (Spring Data JPA, JdbcClient, ...)

    public PageController(PostRepository posts) { this.posts = posts; }

    @GetMapping("/old-page")
    String retired() {
        throw new ResponseStatusException(HttpStatus.GONE); // retired path, no successor: 410 (RTE-004)
    }

    @GetMapping("/blog/{slug}")
    String post(@PathVariable String slug, Model model) {
        var post = posts.findBySlug(slug)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND)); // unknown slug (sg-probe-404): 404 before rendering
        model.addAttribute("post", post);
        return "blog/show";
    }
}
