package com.example.contact;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.concurrent.ConcurrentHashMap;
import org.springframework.stereotype.Component;

@Component
public class ContactRateLimiter {
    private static final int LIMIT = 5;                 // SEC-054: 5 submissions ...
    private static final long WINDOW_MS = 10 * 60_000L; // ... per 10 minutes per client
    private final ConcurrentHashMap<String, Deque<Long>> hits = new ConcurrentHashMap<>();

    public boolean allow(String client) {
        long now = System.currentTimeMillis();
        if (hits.size() > 10_000) { // keep memory bounded
            hits.values().removeIf(q -> { synchronized (q) { return q.isEmpty() || now - q.peekLast() > WINDOW_MS; } });
        }
        Deque<Long> q = hits.computeIfAbsent(client, k -> new ArrayDeque<>());
        synchronized (q) {
            while (!q.isEmpty() && now - q.peekFirst() > WINDOW_MS) q.pollFirst();
            if (q.size() >= LIMIT) return false;
            q.addLast(now);
            return true;
        }
    }
}
