package com.example.contact;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import jakarta.validation.Valid;
import java.net.URI;
import java.net.http.HttpClient;
import java.time.Duration;
import java.util.Map;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.client.JdkClientHttpRequestFactory;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.ModelAttribute;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.client.RestClient;
import org.springframework.web.client.RestClientException;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.web.servlet.View;

@Controller
public class ContactController {
    private static final Logger log = LoggerFactory.getLogger(ContactController.class);
    private final RestClient webhook;
    private final URI webhookUrl;
    private final ContactRateLimiter limiter;

    public ContactController(ContactRateLimiter limiter, @Value("${FORM_WEBHOOK_URL}") String webhookUrl) {
        HttpClient http = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(3)).build();
        JdkClientHttpRequestFactory factory = new JdkClientHttpRequestFactory(http);
        factory.setReadTimeout(Duration.ofSeconds(8));
        this.webhook = RestClient.builder().requestFactory(factory).build();
        this.webhookUrl = URI.create(webhookUrl);
        this.limiter = limiter;
    }

    @GetMapping("/contact")
    String form(Model model) {
        model.addAttribute("form", new ContactForm());
        return "contact";
    }

    @GetMapping("/contact/thanks")
    String thanksPage() { return "contact-thanks"; }

    @PostMapping("/contact")
    String submit(@Valid @ModelAttribute("form") ContactForm form, BindingResult errors,
                  HttpServletRequest request, HttpServletResponse response) {
        if (!limiter.allow(request.getRemoteAddr())) {
            response.setHeader("Retry-After", "600");
            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS); // 429 (SEC-054)
        }
        if (!form.getWebsite().isEmpty()) return thanks(request); // honeypot filled: look successful, do nothing
        if (errors.hasErrors()) {
            response.setStatus(HttpStatus.BAD_REQUEST.value());
            return "contact"; // re-render with the field errors
        }
        try {
            webhook.post()
                .uri(webhookUrl) // the real destination (UX-001); replace this call with your provider's if it is not a webhook
                .contentType(MediaType.APPLICATION_JSON)
                .body(Map.of("name", form.getName(), "email", form.getEmail(), "message", form.getMessage()))
                .retrieve()
                .onStatus(status -> !status.is2xxSuccessful(), (req, res) -> {
                    throw new RestClientException("webhook answered " + res.getStatusCode());
                })
                .toBodilessEntity();
        } catch (RestClientException e) {
            log.warn("contact delivery failed", e);
            throw new ResponseStatusException(HttpStatus.BAD_GATEWAY); // RES-008: never a success page when delivery failed
        }
        return thanks(request);
    }

    private static String thanks(HttpServletRequest request) {
        request.setAttribute(View.RESPONSE_STATUS_ATTRIBUTE, HttpStatus.SEE_OTHER); // 303, not the 302 "redirect:" sends by default
        return "redirect:/contact/thanks";
    }
}
