package com.example.web;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.security.SecureRandom;
import java.util.Base64;
import org.springframework.web.filter.OncePerRequestFilter;

public class CspNonceFilter extends OncePerRequestFilter {
    private static final SecureRandom RANDOM = new SecureRandom();
    // SEC-010 / SEC-075: nonce + strict-dynamic (host sources ignored), no unsafe-inline, object-src and base-uri locked, frame-ancestors present.
    // With analytics add to connect-src: https://www.google-analytics.com https://*.google-analytics.com https://*.analytics.google.com
    // and to img-src: https://www.google-analytics.com (never put Google hosts in script-src; see the consent-loader recipe).
    private static final String POLICY = "default-src 'self'; script-src 'self' 'nonce-{NONCE}' 'strict-dynamic'; "
            + "style-src 'self' 'nonce-{NONCE}'; img-src 'self' data:; font-src 'self'; connect-src 'self'; "
            + "object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'none'; upgrade-insecure-requests";

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
            throws ServletException, IOException {
        byte[] bytes = new byte[16];
        RANDOM.nextBytes(bytes);
        String nonce = Base64.getEncoder().encodeToString(bytes); // fresh per response
        request.setAttribute("cspNonce", nonce); // templates read it as ${cspNonce}
        response.setHeader("Content-Security-Policy", POLICY.replace("{NONCE}", nonce));
        chain.doFilter(request, response);
    }
}
