package com.example.web;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.header.HeaderWriterFilter;
import org.springframework.security.web.header.writers.ReferrerPolicyHeaderWriter.ReferrerPolicy;

@Configuration
public class SecurityConfig {
    @Bean
    SecurityFilterChain web(HttpSecurity http) throws Exception {
        http
            .addFilterBefore(new CspNonceFilter(), HeaderWriterFilter.class)
            .headers(h -> h
                // Referrer-Policy: strict-origin-when-cross-origin
                .referrerPolicy(r -> r.policy(ReferrerPolicy.STRICT_ORIGIN_WHEN_CROSS_ORIGIN))
                // Permissions-Policy: camera=(), microphone=(), geolocation=()
                .permissionsPolicyHeader(p -> p.policy("camera=(), microphone=(), geolocation=()"))
                // Strict-Transport-Security: max-age=63072000; includeSubDomains (HTTPS requests only)
                .httpStrictTransportSecurity(s -> s.maxAgeInSeconds(63072000).includeSubDomains(true)))
            // public marketing site; add requestMatchers(...).authenticated() for private routes.
            // CSRF stays on (Spring Security default); the form-handler recipe relies on it.
            .authorizeHttpRequests(a -> a.anyRequest().permitAll());
        return http.build();
    }
}
