package com.example.seo;

import java.util.List;
import org.springframework.core.env.Environment;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

@RestController
public class SeoController {
    private static final List<String> PUBLIC_PATHS = List.of("/", "/about", "/contact", "/privacy"); // your indexable pages

    private final boolean production;
    private final String siteUrl;

    public SeoController(Environment env) {
        this.production = "production".equals(env.getProperty("DEPLOY_ENV")); // IDX-005: anything else is non-production
        this.siteUrl = env.getProperty("SITE_URL", "https://example.com");
    }

    @GetMapping(value = "/robots.txt", produces = MediaType.TEXT_PLAIN_VALUE)
    public String robots() {
        if (!production) {
            return "User-agent: *\nDisallow: /\n"; // no Sitemap line outside production
        }
        // Disallow only app/API/private paths, never CSS, JS or image paths (/assets/ stays crawlable)
        return "User-agent: *\nAllow: /\nDisallow: /api/\nDisallow: /actuator/\n\nSitemap: " + siteUrl + "/sitemap.xml\n";
    }

    @GetMapping(value = "/sitemap.xml", produces = MediaType.APPLICATION_XML_VALUE)
    public String sitemap() {
        if (!production) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND); // non-production: no sitemap
        }
        StringBuilder xml = new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n")
            .append("<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\n");
        for (String path : PUBLIC_PATHS) {
            xml.append("  <url><loc>").append(escape(siteUrl + path)).append("</loc></url>\n");
        }
        return xml.append("</urlset>\n").toString();
    }

    private static String escape(String s) {
        return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;").replace("'", "&apos;");
    }
