package com.example.seo;

import jakarta.servlet.DispatcherType;
import jakarta.servlet.Filter;
import jakarta.servlet.http.HttpServletResponse;
import java.util.EnumSet;
import org.springframework.boot.web.servlet.FilterRegistrationBean;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.Ordered;
import org.springframework.core.env.Environment;

@Configuration
public class NoindexFilterConfig {
    // IDX-005: outside production EVERY response (pages, assets, errors, robots.txt) carries X-Robots-Tag; in production the filter is disabled.
    @Bean
    FilterRegistrationBean<Filter> noindexOutsideProduction(Environment env) {
        Filter noindex = (request, response, chain) -> {
            ((HttpServletResponse) response).setHeader("X-Robots-Tag", "noindex, nofollow");
            chain.doFilter(request, response);
        };
        FilterRegistrationBean<Filter> registration = new FilterRegistrationBean<>(noindex);
        registration.setEnabled(!"production".equals(env.getProperty("DEPLOY_ENV")));
        registration.setOrder(Ordered.HIGHEST_PRECEDENCE);
        registration.setDispatcherTypes(EnumSet.allOf(DispatcherType.class)); // include the /error dispatch
        return registration;
    }
}
